350: 	private Order saveOrderInternal(Order order, OrderContext orderContext) {
351: 		if (order.getOrderId() == null) {
352: 			if (order.getOrderNumber() == null) {
353: 				setProperty(order, "orderNumber", getOrderNumberGenerator().getNewOrderNumber(orderContext));
354: 			}
355: 
356: 			//DC orders should auto expire upon creating them
357: 			if (DISCONTINUE == order.getAction()) {
358: 				order.setAutoExpireDate(order.getDateActivated());
359: 			} else if (order.getAutoExpireDate() != null) {
360: 				Calendar cal = Calendar.getInstance();
361: 				cal.setTime(order.getAutoExpireDate());
362: 				int hours = cal.get(Calendar.HOUR_OF_DAY);
363: 				int minutes = cal.get(Calendar.MINUTE);
364: 				int seconds = cal.get(Calendar.SECOND);
365: 				cal.get(Calendar.MILLISECOND);
